package com.infinitylibrary.community;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.model.*;
import com.infinitylibrary.diversity.*;
import com.infinitylibrary.gui.LibraryMenu;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.block.data.BlockData;
import java.util.*;

/** Owner-only client block preview. Never writes blocks or loads chunks. */
public final class PreviewManager {
    private static final class Preview {final Player player;final Room room;final World world;final Vector3i origin;RoomTransform transform=RoomTransform.IDENTITY;UUID seed=UUID.randomUUID();DiversityComposition diversity;Map<Vector3i,BlockData> blocks;List<Vector3i> order;final Set<Vector3i> sent=new HashSet<>();int cursor;final long expires;Preview(Player p,Room room,Vector3i origin,int seconds){player=p;this.room=room;world=p.getWorld();this.origin=origin;expires=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(seconds);}}
    private final InfinityLibraryPlugin plugin;private final Map<UUID,Preview> active=new LinkedHashMap<>();private final int task;private int ticks;
    public PreviewManager(InfinityLibraryPlugin p){plugin=p;task=Bukkit.getScheduler().scheduleSyncRepeatingTask(plugin,this::tick,1,1);}
    private void admin(Player p){if(!p.hasPermission("infinitylibrary.admin"))throw new IllegalArgumentException("Room preview requires infinitylibrary.admin.");}
    public int activeCount(){return active.size();}
    public void start(Player p,String id){admin(p);Room room=plugin.getRoomManager().get(id).orElseThrow(()->new IllegalArgumentException("Room not found."));long volume=(long)room.size().x()*room.size().y()*room.size().z();if(volume>Math.max(1,Math.min(65536,plugin.getConfig().getLong("preview.max-volume",32768))))throw new IllegalArgumentException("Room exceeds the configured client preview volume limit.");if(!active.containsKey(p.getUniqueId())&&active.size()>=4)throw new IllegalArgumentException("Four builders are already previewing rooms.");double angle=Math.toRadians(p.getLocation().getYaw());double forward=Math.max(room.size().x(),room.size().z())/2.0+8;Vector3i origin=new Vector3i((int)Math.floor(p.getLocation().getX()-Math.sin(angle)*forward-room.size().x()/2.0),p.getLocation().getBlockY(),(int)Math.floor(p.getLocation().getZ()+Math.cos(angle)*forward-room.size().z()/2.0));Preview next=new Preview(p,room,origin,Math.max(10,Math.min(300,plugin.getConfig().getInt("preview.duration-seconds",90))));next.diversity=DiversityComposition.resolve(room,next.seed);prepare(next);stop(p);active.put(p.getUniqueId(),next);p.sendMessage("Preview is visible only to you; the world is unchanged. Green particles mark active doors, yellow decoration areas, purple Diversity targets. /il preview stop to restore your view.");menu(p);}
    private void validate(Preview s){Vector3i size=s.transform.transformedSize(s.room.size());int radius=Math.max(16,Math.min(128,plugin.getConfig().getInt("preview.max-distance",80)));if(s.origin.y()<s.world.getMinHeight()||(long)s.origin.y()+size.y()>s.world.getMaxHeight())throw new IllegalArgumentException("Preview would exceed world height.");Vector3i end=s.origin.add(size).subtract(new Vector3i(1,1,1));if(!s.world.getWorldBorder().isInside(s.origin.toLocation(s.world))||!s.world.getWorldBorder().isInside(end.toLocation(s.world)))throw new IllegalArgumentException("Preview is outside world boundaries.");for(int x=s.origin.x()>>4;x<=end.x()>>4;x++)for(int z=s.origin.z()>>4;z<=end.z()>>4;z++)if(!s.world.isChunkLoaded(x,z))throw new IllegalArgumentException("Preview needs already loaded chunks. Try a smaller room or another location.");if(s.origin.toLocation(s.world).distanceSquared(s.player.getLocation())>radius*radius||end.toLocation(s.world).distanceSquared(s.player.getLocation())>radius*radius)throw new IllegalArgumentException("Preview is too far away for the configured range.");var p=Vector3i.from(s.player.getLocation());if(p.x()>=s.origin.x()-2&&p.x()<=end.x()+2&&p.z()>=s.origin.z()-2&&p.z()<=end.z()+2)throw new IllegalArgumentException("Preview would surround you. Face an open space and retry.");}
    private void prepare(Preview s){validate(s);Map<Vector3i,BlockData> map=new LinkedHashMap<>();Vector3i size=s.transform.transformedSize(s.room.size());BlockData air=Material.AIR.createBlockData();for(int x=0;x<size.x();x++)for(int y=0;y<size.y();y++)for(int z=0;z<size.z();z++)map.put(s.origin.add(new Vector3i(x,y,z)),air);
        for(RoomBlock b:s.room.blocks())if(s.diversity.patches().stream().noneMatch(p->p.contains(b.position())))put(s,map,b);
        Map<String,List<VariationArea>> legacy=new LinkedHashMap<>();for(var v:s.room.variations())legacy.computeIfAbsent(v.category(),k->new ArrayList<>()).add(v);Random random=new Random(s.seed.getMostSignificantBits()^s.seed.getLeastSignificantBits());for(var group:legacy.values()){Collections.shuffle(group,random);for(var v:group)if(v.chancePercent()>0&&random.nextDouble()*100<v.chancePercent()){for(RoomBlock b:v.blocks())put(s,map,b);break;}}
        for(var patch:s.diversity.patches())for(RoomBlock b:patch.blocks())put(s,map,b);
        var props=plugin.getPropManager().compose(s.room,s.seed);for(var area:props.areas())for(int x=0;x<area.size().x();x++)for(int y=0;y<area.size().y();y++)for(int z=0;z<area.size().z();z++)map.put(world(s,area.min().add(new Vector3i(x,y,z))),air);for(RoomBlock b:props.blocks())put(s,map,b);
        for(ConnectionPoint cp:s.diversity.connections(s.room))if(cp.width()<=Math.max(s.room.size().x(),s.room.size().z())&&cp.height()<=s.room.size().y())for(Vector3i cell:cp.cells()){Vector3i at=world(s,cell);if(map.containsKey(at))map.put(at,air);}
        s.blocks=map;s.order=List.copyOf(map.keySet());s.cursor=0;
    }
    private Vector3i world(Preview s,Vector3i local){return s.origin.add(s.transform.transform(local,s.room.size()));}
    private void put(Preview s,Map<Vector3i,BlockData> map,RoomBlock b){BlockData data=Bukkit.createBlockData(b.blockData());plugin.getGenerationEngine().rotateData(data,s.transform);Vector3i at=world(s,b.position());if(map.containsKey(at))map.put(at,data);}
    private void restore(Preview s){if(s.player.getWorld()!=s.world){s.sent.clear();return;}for(Vector3i p:s.sent)if(s.world.isChunkLoaded(p.x()>>4,p.z()>>4))s.player.sendBlockChange(p.toLocation(s.world),s.world.getBlockAt(p.x(),p.y(),p.z()).getBlockData());s.sent.clear();}
    public void stop(Player p){Preview s=active.remove(p.getUniqueId());if(s!=null&&p.isOnline())restore(s);}
    public void clear(){for(var s:new ArrayList<>(active.values()))stop(s.player);}
    public void shutdown(){clear();Bukkit.getScheduler().cancelTask(task);}
    public void variant(Player p,String areaId,String choice){admin(p);Preview s=require(p);DiversityArea area=s.room.diversityAreas().stream().filter(a->a.id().equals(areaId)).findFirst().orElseThrow(()->new IllegalArgumentException("Diversity area not found in this preview."));DiversityVariant v=choice.equals("default")?null:area.variants().stream().filter(x->x.id().equals(choice)).findFirst().orElseThrow(()->new IllegalArgumentException("Variant not found."));List<RoomBlock> blocks=v==null?s.room.blocks().stream().filter(b->area.bounds().contains(b.position())).toList():v.blocks().stream().map(b->new RoomBlock(area.min().add(b.position()),b.blockData())).toList();var patch=new DiversityComposition.Patch(area.id(),area.min(),area.size(),choice,blocks,v==null?List.of():v.connections().stream().map(cp->cp.offset("div_"+area.id()+"_"+cp.id(),area.min())).toList());List<DiversityComposition.Patch> patches=new ArrayList<>(s.diversity.patches());patches.removeIf(x->x.areaId().equals(areaId));patches.add(patch);restore(s);s.diversity=new DiversityComposition(patches);prepare(s);menu(p);}
    private Preview require(Player p){Preview s=active.get(p.getUniqueId());if(s==null)throw new IllegalArgumentException("Start /il preview <roomId> first.");return s;}
    public void menu(Player p){admin(p);Preview s=require(p);LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.PREVIEW,27,"Library • Room preview");var w=plugin.getBookWritingManager();w.icon(m.getInventory(),4,Material.BRICKS,s.room.id(),"§7Size: "+s.room.size()+" · "+s.room.type(),"§7Active doors: "+s.diversity.connections(s.room).size(),"§7Props: "+s.room.propAreas().size()+" · Diversity: "+s.room.diversityAreas().size());w.icon(m.getInventory(),10,Material.COMPASS,"Rotate 90°");w.icon(m.getInventory(),12,Material.GLASS,"Mirror X");w.icon(m.getInventory(),14,Material.ENDER_PEARL,"Reroll props and Diversity");w.icon(m.getInventory(),16,Material.BARRIER,"Stop preview");w.icon(m.getInventory(),22,Material.PRISMARINE_SHARD,"Select a Diversity variant");p.openInventory(m.getInventory());}
    public void handle(Player p,int slot){admin(p);Preview s=require(p);if(slot==16){stop(p);if(plugin.getRoomManager().getActive(s.room.id()).isPresent())plugin.getGuiManager().openRoomDetails(p,s.room.id());else plugin.getGuiManager().openRoomEditor(p);return;}if(slot==22){List<ManagedDialogs.Button> buttons=new ArrayList<>();for(var area:s.room.diversityAreas()){buttons.add(new ManagedDialogs.Button(area.id()+" / default",r->variant(p,area.id(),"default")));for(var v:area.variants())buttons.add(new ManagedDialogs.Button(area.id()+" / "+v.id(),r->variant(p,area.id(),v.id())));}if(buttons.size()>40){p.sendMessage("Use /il previewvariant <area> <variant|default> for this large variant catalog.");return;}buttons.add(new ManagedDialogs.Button("Back",r->menu(p)));plugin.getManagedDialogs().show(p,"Preview Diversity","Only this preview changes.",List.of(),buttons);return;}
        RoomTransform old=s.transform;if(slot==10)s.transform=new RoomTransform(com.infinitylibrary.model.Rotation.values()[(old.rotation().ordinal()+1)%4],old.flipX(),old.flipZ());else if(slot==12)s.transform=new RoomTransform(old.rotation(),!old.flipX(),old.flipZ());else if(slot==14){s.seed=UUID.randomUUID();s.diversity=DiversityComposition.resolve(s.room,s.seed);}else return;try{validate(s);}catch(RuntimeException ex){s.transform=old;throw ex;}restore(s);prepare(s);menu(p);
    }
    private void point(Player p,Location at,Color color){p.spawnParticle(Particle.DUST,at,1,0,0,0,0,new Particle.DustOptions(color,1.2f));}
    private void corners(Preview s,Vector3i min,Vector3i size,Color color){for(int x:new int[]{0,size.x()-1})for(int y:new int[]{0,size.y()-1})for(int z:new int[]{0,size.z()-1})point(s.player,world(s,min.add(new Vector3i(x,y,z))).toLocation(s.world).add(.5,.5,.5),color);}
    private void tick(){ticks++;int budget=512;for(var s:new ArrayList<>(active.values())){if(!s.player.isOnline()||!s.player.hasPermission("infinitylibrary.admin")||s.player.getWorld()!=s.world||System.nanoTime()>s.expires){stop(s.player);continue;}if(s.player.getLocation().distanceSquared(s.origin.toLocation(s.world))>16384){stop(s.player);continue;}int sent=0;while(s.cursor<s.order.size()&&budget>0&&sent<128){Vector3i pos=s.order.get(s.cursor++);if(!s.world.isChunkLoaded(pos.x()>>4,pos.z()>>4)){stop(s.player);break;}s.player.sendBlockChange(pos.toLocation(s.world),s.blocks.get(pos));s.sent.add(pos);budget--;sent++;}if(ticks%20==0){for(var cp:s.diversity.connections(s.room).stream().limit(32).toList())point(s.player,world(s,cp.position()).toLocation(s.world).add(.5,.6,.5),Color.LIME);for(var area:s.room.propAreas())corners(s,area.min(),area.size(),Color.YELLOW);for(var area:s.room.diversityAreas())corners(s,area.min(),area.size(),Color.FUCHSIA);}}
    }
}
